def place(r):
    if r == 0:
        return "on the positive x-axis"
    elif r == 90:
        return "on the positive y-axis"
    elif r == 180:
        return "on the negative x-axis"
    elif r == 270:
        return "on the negative y-axis"
    elif r < 90:
        return "in quadrant I"
    elif r < 180:
        return "in quadrant II"
    elif r < 270:
        return "in quadrant III"
    else:
        return "in quadrant IV"

def show(label, angle):
    r = angle % 360
    q = (angle - r) // 360
    print(f"{label}: {angle} = 360 * ({q}) + {r}")
    print(f"  drop the {q} whole turns: {r} degrees, {place(r)}")

show("Example 1", 135)
show("Example 2", 765)
show("Example 3", -120)
show("Example 4", -1000)
show("Example 6", 450)
show("Example 9", 900)

practice.solution:
def place(r):
    if r == 0:
        return "positive x-axis"
    elif r == 90:
        return "positive y-axis"
    elif r == 180:
        return "negative x-axis"
    elif r == 270:
        return "negative y-axis"
    elif r < 90:
        return "quadrant I"
    elif r < 180:
        return "quadrant II"
    elif r < 270:
        return "quadrant III"
    else:
        return "quadrant IV"

n = int(input())
for i in range(n):
    angle = int(input())
    r = angle % 360
    print(f"{angle} -> {r}, {place(r)}")
